  "Rufnummern für ein- und ausgehende Anrufe, auch für Deutschland, Österreich und die Schweiz, plus SMS in beide Richtungen.": "Numeri per chiamate in entrata e in uscita, anche per Germania, Austria e Svizzera, più SMS in entrambe le direzioni.",
