  "App-Ereignisse starten Anrufe; Transkripte, Zusammenfassungen und Ergebnisse gehen an tausende Apps.": "Gli eventi delle app avviano chiamate; trascrizioni, riepiloghi ed esiti arrivano a migliaia di app.",
