  "Anbieter": "Gestore",
  "<mark class=\"ph\">[Firmenname]<\/mark> <mark class=\"ph\">[Rechtsform]<\/mark><br><mark class=\"ph\">[Strasse und Nr.]<\/mark><br><mark class=\"ph\">[PLZ Ort]<\/mark>, <mark class=\"ph\">[Land]<\/mark>": "<mark class=\"ph\">[Ragione sociale]<\/mark> <mark class=\"ph\">[Forma giuridica]<\/mark><br><mark class=\"ph\">[Via e numero civico]<\/mark><br><mark class=\"ph\">[CAP Località]<\/mark>, <mark class=\"ph\">[Paese]<\/mark>",
