  "Optional": "Facoltativo",
  "Annahmen: 4,33 Wochen pro Monat, 8-Stunden-Arbeitstag. Kosten mit der einmaligen Einrichtung am unteren Ende der Spanne (Voice {{p:voice-agent.setupMin}}, Chat {{p:chatbot.setupMin}}, Social {{p:social-media.setupMin}}) plus laufende Kosten: beim Voice Agent {{p:voice-agent.monthly}} Grundgebühr pro Monat und 4 Gesprächsminuten pro Anruf zu {{p:voice-agent.perUnit}}, 14 Nachrichten pro Chat und 40 Nachrichten pro Social-Media-Stunde zu je {{p:chatbot.perUnit}}.": "Ipotesi: 4,33 settimane al mese, giornata lavorativa di 8 ore. Costi con la configurazione una tantum al limite inferiore della fascia (Voice {{p:voice-agent.setupMin}}, Chat {{p:chatbot.setupMin}}, Social {{p:social-media.setupMin}}) più i costi correnti: per il Voice Agent {{p:voice-agent.monthly}} di canone base al mese e 4 minuti di chiamata per telefonata a {{p:voice-agent.perUnit}}, 14 messaggi per chat e 40 messaggi per ora di social media a {{p:chatbot.perUnit}} ciascuno.",
  "Gerettete Aufträge rechnen wir vorsichtig: nur unbeantwortete Anrufe, davon 30 % mit Abschluss, und nur wenn der Voice Agent ausgewählt ist. Alle Werte sind Schätzungen und keine Garantie.": "Calcoliamo gli incarichi recuperati con prudenza: solo le chiamate senza risposta, di cui il 30 % concluse con successo, e solo se è selezionato il Voice Agent. Tutti i valori sono stime e non costituiscono una garanzia.",
