  "Hinweis für den Betreiber: Vorlage, keine Rechtsberatung. Alle markierten Platzhalter ausfüllen,": "Nota per il gestore: modello, non consulenza legale. Compilare tutti i segnaposto evidenziati,",
  "nicht zutreffende Abschnitte streichen und den Text vor der Veröffentlichung rechtlich prüfen lassen": "eliminare le sezioni non pertinenti e far verificare il testo da un legale prima della pubblicazione",
  "(Schweiz: revDSG, UWG Art. 3 Abs. 1 lit. s; Deutschland\/EU: DSGVO, DDG § 5, MStV § 18).": "(Svizzera: nLPD, LCSl art. 3 cpv. 1 lett. s; Germania\/UE: GDPR, DDG § 5, MStV § 18).",
  "Empfehlung: Google Fonts lokal einbinden, dann den Abschnitt Schriftarten anpassen.": "Raccomandazione: integrare Google Fonts in locale, poi adeguare la sezione Caratteri.",
