  "Dabei kann eine Übermittlung in ein Land ohne angemessenes Datenschutzniveau stattfinden, abgesichert durch": "Ciò può comportare un trasferimento verso un Paese privo di un livello adeguato di protezione dei dati, tutelato da",
  "Standardvertragsklauseln oder andere Garantie": "clausole contrattuali standard o altra garanzia",
